def valid(matches):
    if not isinstance(matches, list) or not (3 <= len(matches) <= 10):
        return False
    for m in matches:
        if not isinstance(m, str) or len(m) != 2:
            return False
        if not all('A' <= ch <= 'Z' for ch in m) or not m[0] < m[1]:
            return False
    firsts = [m[0] for m in matches]
    if firsts != sorted(firsts):
        return False
    adj = {}
    for m in matches:
        adj.setdefault(m[0], set()).add(m[1])
        adj.setdefault(m[1], set()).add(m[0])
    if 'A' not in adj:
        return False
    seen = set()
    teams = 0
    for s in adj:
        if s in seen:
            continue
        teams += 1
        seen.add(s)
        stack = [s]
        while stack:
            x = stack.pop()
            for y in adj[x]:
                if y not in seen:
                    seen.add(y)
                    stack.append(y)
    return teams == 2

